export const RIVET_PAGE_DATA_ELEMENT_ID = 'rivet-page';
export const SIGN_IN_CALLBACK_COMPLETE_PATH = '/complete';

export type CanvasShareDirection = {
  label: string;
  brief: string;
  shareUrl: string;
};

export type SharedShellRivetPage =
  | { kind: 'preview-waiting' }
  | { kind: 'sign-in-callback' }
  | {
      kind: 'canvas-share';
      prompt: string;
      directions: CanvasShareDirection[];
    };

export type RivetPage = { kind: 'empty-project' } | SharedShellRivetPage;

export type ConnectResultMessage = {
  type: 'rivet:connect-result';
  provider: string;
  status: 'connected' | 'error';
  message?: string;
};

export type ConnectResultClosePolicy = 'always' | 'after-notifying-opener';

export type HostedRivetPage =
  | { kind: 'google-sign-in'; initiator: string; providerAuthUrl: string }
  | { kind: 'sign-in-link-expired' }
  | {
      kind: 'connect-result';
      result: ConnectResultMessage;
      notice: string;
      closePolicy: ConnectResultClosePolicy;
    };

export type RivetPageShareCard = {
  description: string;
  imageUrl: string;
};

export type RivetPageHead = {
  title: string;
  shareCard?: RivetPageShareCard;
  robots?: 'noindex';
};
